#include <iostream>
#include <string>
#include <unordered_set>
#include <vector>
using namespace std;
typedef unsigned long long u64;
typedef vector<u64> Big;  // little-endian limbs, base 1e9
static const u64 BASE = 1000000000ULL;

static Big parse_big(const string& dec) {
    Big r;
    for (long long end = (long long)dec.size(); end > 0; end -= 9) {
        long long b = end - 9 < 0 ? 0 : end - 9;
        r.push_back(stoull(dec.substr(b, end - b)));
    }
    while (!r.empty() && r.back() == 0) r.pop_back();
    return r;
}
static void mul_small(Big& a, u64 m) {
    u64 carry = 0;
    for (auto& x : a) { u64 cur = x * m + carry; x = cur % BASE; carry = cur / BASE; }
    while (carry) { a.push_back(carry % BASE); carry /= BASE; }
}
static void add_big(Big& a, const Big& b) {
    u64 carry = 0;
    for (size_t i = 0; i < max(a.size(), b.size()) || carry; i++) {
        if (i == a.size()) a.push_back(0);
        u64 cur = a[i] + (i < b.size() ? b[i] : 0) + carry;
        a[i] = cur % BASE; carry = cur / BASE;
    }
}
static u64 divmod_small(Big& a, u64 d) {
    u64 rem = 0;
    for (size_t i = a.size(); i-- > 0;) { u64 cur = rem * BASE + a[i]; a[i] = cur / d; rem = cur % d; }
    while (!a.empty() && a.back() == 0) a.pop_back();
    return rem;
}
static string big_str(const Big& a) {
    if (a.empty()) return "0";
    string r = to_string(a.back());
    for (size_t i = a.size() - 1; i-- > 0;) { string p = to_string(a[i]); r += string(9 - p.size(), '0') + p; }
    return r;
}

static bool digits(const string& s) {
    if (s.empty()) return false;
    for (char c : s) if (c < '0' || c > '9') return false;
    return true;
}

static string verdict(const vector<string>& f, const unordered_set<string>& seen, long long last, string& units, long long& qty, long long& ts) {
    if (f.size() != 6) return "BAD_FIELDS";
    const string &id = f[0], &sy = f[1], &sd = f[2], &q = f[3], &pr = f[4], &t = f[5];
    if (id.empty()) return "BAD_ID";
    for (char c : id) if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))) return "BAD_ID";
    if (sy.empty() || sy.size() > 6) return "BAD_SYMBOL";
    for (char c : sy) if (c < 'A' || c > 'Z') return "BAD_SYMBOL";
    if (sd != "B" && sd != "S") return "BAD_SIDE";
    if (!digits(q) || q[0] == '0' || q.size() > 10 || stoll(q) > 1000000000LL) return "BAD_QTY";
    qty = stoll(q);
    size_t dot = pr.find('.');
    string ip = dot == string::npos ? pr : pr.substr(0, dot);
    string fp = dot == string::npos ? "" : pr.substr(dot + 1);
    bool ok = digits(ip) && (dot == string::npos || (digits(fp) && fp.size() <= 4));
    if (ok) {
        while (fp.size() < 4) fp += '0';
        units = ip + fp;
        ok = units.find_first_not_of('0') != string::npos;
    }
    if (!ok) return "BAD_PRICE";
    if (!digits(t) || (t.size() > 1 && t[0] == '0') || t.size() > 13 || stoll(t) > 1000000000000LL) return "BAD_TS";
    ts = stoll(t);
    if (seen.count(id)) return "DUP_ID";
    if (ts < last) return "OUT_OF_ORDER";
    return "";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    int n = stoi(line);
    unordered_set<string> seen;
    long long last = 0, valid = 0;
    Big total;
    for (int k = 0; k < n; k++) {
        if (!getline(cin, line)) line.clear();
        if (!line.empty() && line.back() == '\r') line.pop_back();
        vector<string> f;
        size_t st = 0;
        while (true) {
            size_t c = line.find(',', st);
            if (c == string::npos) { f.push_back(line.substr(st)); break; }
            f.push_back(line.substr(st, c - st));
            st = c + 1;
        }
        string units; long long qty = 0, ts = 0;
        string e = verdict(f, seen, last, units, qty, ts);
        if (!e.empty()) { cout << e << '\n'; continue; }
        seen.insert(f[0]);
        last = ts;
        valid++;
        Big u = parse_big(units);
        mul_small(u, (u64)qty);
        add_big(total, u);
        cout << "OK\n";
    }
    u64 fr = divmod_small(total, 10000);
    string fs = to_string(fr);
    cout << "VALID " << valid << "\nNOTIONAL " << big_str(total) << '.' << string(4 - fs.size(), '0') << fs << '\n';
    return 0;
}

